function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const division_input = multisetDiff(before.division_input, after.division_input);
  const probe = multisetDiff(before.probe, after.probe);
  return {
    rels: [
      { rel: "division_input", add: division_input.add, del: division_input.del },
      { rel: "probe", add: probe.add, del: probe.del },
    ],
    carryPending: false,
  };
}

